INSERT INTO products VALUES (217, 2, 'Biotage Extrahera', 'automated SPE/SLE sample-preparation workstation', 'prior', NULL);
INSERT INTO products VALUES (217, 3, 'Biotage Initiator+ / Alstra+', 'microwave organic and peptide synthesizers', 'prior', NULL);
INSERT INTO israel_entities VALUES (217, 'Bargal Analytical Instruments Ltd.', 'ברגל ציוד אנליטי', 'distributor', 'Biotage distributor for Israel: Biotage''s own live contact page lists ''BARGAL'' (sales@bargal.co.il) for Israel with product areas Organic & Peptide, Bioanalytical testing and Environmental testing; Bargal''s live site carries Biotage Initiator+ / Initiator 2.0 microwave synthesizers, Syro Wave peptide synthesizer, Isolera / Flash 75-400 flash purification and RapidTrace+ SPE workstation pages', 'https://www.bargal.co.il', '+972-3-979-6533', 'sales@bargal.co.il', '10 Shaked Street, Modi''in Industrial Park, Shoham 6085102', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.biotage.com/company/contact');
