INSERT INTO products VALUES (246, 3, 'BLAUBRAND volumetric glassware', 'Class A flasks, pipettes, burettes', 'prior', NULL);
INSERT INTO israel_entities VALUES (246, 'Labotal Scientific Equipment Ltd.', 'לבוטל', 'distributor', 'VACUUBRAND diaphragm and ATEX vacuum pumps - listed on VACUUBRAND''s live ''Contact persons worldwide'' page as its Israel contact (Mevaseret Zion), alongside a VACUUBRAND area sales manager for Israel; BRAND liquid handling (Transferpette S / electronic / alpha, carried since 2018 per Labotal''s own news page) is not reflected on BRAND''s worldwide sales list', 'https://labotal.co.il', '+972 2-579-9222', 'Sales@labotal.co.il', 'Hashalom Rd., Abu Ghosh 9084500 (mail: Mevaseret Zion)', 'https://labotal.co.il/contact/', 2026, 'current', 'prior_research', NULL, 'https://www.vacuubrand.com/service-advice/contact/contacts-worldwide');
INSERT INTO israel_entities VALUES (246, 'Yoel Naim Ltd.', NULL, 'distributor', 'BRAND (liquid handling, volumetric ware) distributor and service partner for Israel - named on BRAND''s live ''Sales and Consulting worldwide'' page (industrial area, Rehovot); website not found', NULL, NULL, NULL, NULL, NULL, 2026, 'new', 'prior_research', NULL, 'https://www.brand.de/en/company/sales-worldwide');
