INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (257, 'buchi', 'Buchi', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Buchi', 'https://www.thomassci.com/browse-by/suppliers/buchi', NULL, NULL, NULL, 'https://www.buchi.com', 'prior', 'Switzerland', 'שווייץ', 'Flawil (St. Gallen)', NULL, 1939, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 'ציוד', 'catalog_facet', NULL, 800, 2025, 'company', 'prior', 204, 'USD ~204 million (aggregator estimate; other aggregators range from USD 8M to USD 750M)', 'undated aggregator estimate (c. 2024)', 'estimate', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Dr. Golik''s live site re-confirms it as the Israeli BUCHI channel with a BUCHI manufacturer page, Rotavapor and laboratory-evaporation pages and a BUCHI Pure chromatography page, plus Kugelrohr and fraction-collector listings, so the scope is wider than evaporation alone. BUCHI''s own ''BUCHI Worldwide'' support page includes Israel in its country filter but the partner name was not visible in the snippet. No other Israeli BUCHI channel surfaced. A search for ''Buchi Rotavapor'' restricted to Israeli distributor domains returned Dr. Golik''s own BUCHI manufacturer page, its ''Dr. Golik - BUCHI - Laboratory Evaporation'' page and a Hebrew Rotavapor product page (noting the R-100 discontinuation and pointing to R-80/R-300), so Dr. Golik (ד"ר גוליק) is recorded as the Israeli distributor. MRC pages in the same results concern MRC''s own-brand rotary evaporators, not BUCHI. BUCHI''s own distributor locator (buchi.com) was not searched within the budget, so whether Dr. Golik also carries BUCHI''s extraction, Kjeldahl, NIR or spray-drying lines is unconfirmed.', '+41 71 394 63 63', NULL, 'Meierseggstrasse 40, Postfach, 9230 Flawil, Switzerland', 'https://www.buchi.com/en/support/contact', 'https://www.americanpharmaceuticalreview.com/105589-BUCHI-Labortechnik-AG/', NULL);
INSERT INTO products VALUES (257, 1, 'Rotavapor R-300', 'modular rotary evaporator system', 'prior', NULL);
INSERT INTO products VALUES (257, 2, 'Mini Spray Dryer S-300 / B-290', 'laboratory spray dryers', 'prior', NULL);
INSERT INTO products VALUES (257, 3, 'KjelMaster K-375 / Kjeldahl line', 'nitrogen and protein determination systems', 'prior', NULL);
INSERT INTO israel_entities VALUES (257, 'Dr. Golik Scientific Solutions', 'ד"ר גוליק', 'distributor', 'BUCHI laboratory evaporation (Rotavapor R-80, R-300, R-220 EX/R-250 EX; R-100 discontinued), I-300/I-300 Pro interfaces, V-300/V-600 vacuum pumps, F-305 chillers, Glass Oven B-585 Kugelrohr, Fraction Collector C-660 and the BUCHI ''Pure'' chromatography system - live BUCHI manufacturer page, Rotavapor page, ''Laboratory Evaporation'' and ''Pure System'' pages; scope now extends to chromatography', 'https://www.golik.co.il', '+972-3-518-7555', 'marketing@golik.co.il', '34 Kibbutz Galuyot St, Tel Aviv 66550', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.golik.co.il/manufacturers/buchi');
INSERT INTO israel_entities VALUES (257, 'Israel Scientific Instruments Ltd. (ISI)', NULL, 'distributor', 'listed as a brand on the distributor''s site', 'https://www.isil.co.il', '+972 3-923-2202', 'info@isil.co.il', '32 Shacham St., P.O. Box 7790, Petah Tikva 49170', NULL, 2026, 'current', 'distributor_site_sweep', 'exact', 'https://www.isil.co.il/index.php?dir=site&page=teams&op=category&cs=8');
