INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (345, 'cole parmer', 'Cole parmer', 'D+T+Q', 'https://www.dutscher.com/search?initialFilters=brand:Cole+parmer', 'https://www.thomassci.com/browse-by/suppliers/cole-parmer', 'yes', NULL, NULL, 'https://www.antylia.com', 'prior', 'USA', 'ארה"ב', 'Vernon Hills, Illinois', 'Brookfield Business Partners & CDPQ (since May 2025)', 1955, 'Lab distribution & own-brand products', 'ציוד', 'catalog_facet', 'medical and environmental products company', 2000, 2024, 'estimate', 'prior', 400, 'approx. USD 400 million (third-party directory estimate)', 'n/a (directory estimate seen Oct 2026)', 'estimate', 'prior', 'estimate', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Medent''s live product pages re-confirm it as an Israeli channel for Antylia''s Stuart brand (stirrers, hotplates, rotary evaporators, rotators, water stills) and add the Jenway brand (6305 UV/Vis spectrophotometer). Cole-Parmer''s own site names no Israeli distributor; its privacy policy only states that Antylia Scientific operates through direct fulfilment and distributors worldwide. The channel for the Cole-Parmer brand itself, Techne and Environmental Express remains unidentified. General search (''Cole-Parmer'' OR ''Antylia'' Israel distributor/נציג/יבואן) returned no Israeli entity and no Israel listing on Antylia/IDEX distributor pages (only Australia/NZ: John Morris; Italy). A search restricted to Israeli distributor domains found Medent (medent.co.il) listing Stuart-brand shakers, heated stirrers and water stills. No Israeli partner found for the Cole-Parmer brand itself, Jenway, Techne or Environmental Express; Masterflex is now Avantor and was not searched. Antylia''s own ''find a distributor'' page was not fetched (fetching blocked). Corporate note seen in snippet: Brookfield and CDPQ completed the acquisition of Antylia Scientific for approximately USD 1.3 billion (CDPQ news release).', '+1 800-323-4340', 'sales@antylia.com', '625 East Bunker Court, Vernon Hills, IL 60061, USA', NULL, 'https://www.thomasnet.com/company/cole-parmer-1148924/profile', 'Q5142613');
INSERT INTO products VALUES (345, 1, 'Jenway spectrophotometers', 'UV/Vis and visible benchtop spectrophotometers', 'prior', NULL);
