INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (584, 'hach', 'Hach', 'D+Q', 'https://www.dutscher.com/search?initialFilters=brand:Hach', NULL, 'yes', NULL, NULL, 'https://www.hach.com', 'prior', 'USA', 'ארה"ב', 'Loveland, Colorado', 'Veralto Corporation', 1947, 'Water & electrochemical analysis', 'כימיה', 'catalog_facet', NULL, 17000, 2025, 'parent', 'prior', 3321, 'USD 3,321 million', 'FY2025', 'segment', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'partial', 'חיפוש חלקי', 2026, 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Modotec''s live website (supplier page plus analyzers, controllers, turbidity, spectrophotometer, oxygen/UV meter and sampler pages) presents Hach as its supplier across the online and laboratory water-analysis range, so the relationship is documented on the distributor''s current site and the scope is broader than the Hach Flow listing recorded before; the search engine dates those pages at about 4-7 years old. Hach''s own side could not be confirmed this session: hach.com''s global-distributor page is a map picker whose Israel entry was not visible, and an unrestricted search found only Hach''s Dubai (MENA) site and ESS-ME, a Middle East distributor that does not name Israel. Marked partial because the manufacturer-side listing seen earlier (nz.hach.com/flow, ~5 years old) remains the only Hach-side confirmation. Hach''s own ''Hach Flow'' distributor page (nz.hach.com/flow, about five years old) lists Modotec Ltd., Akko (modotec@modotec.co.il) under Israel for Hach Flow products. No Israeli distributor was found for Hach''s core lab/water-analysis lines (DR spectrophotometers, HQ meters, 2100Q turbidimeters): searches across 43 Israeli distributor domains, Hebrew queries, hach.com''s global-distributor pages and model-number queries surfaced nothing, and Hach''s regional contact is Hach Middle East & Africa in Dubai (+971 4 303 1700). Treat the Modotec listing as stale and partial in scope, and verify.', '+1 800-227-4224 (toll-free); +1 970-669-3050 (international line)', 'orders@hach.com; support@hach.com', 'P.O. Box 389, Loveland, CO 80539, USA (street address 5600 Lindbergh Drive, Loveland, CO per directories only)', 'https://hach.com/contact', 'https://hach.com/contact', NULL);
INSERT INTO products VALUES (584, 1, 'DR3900 / DR6000', 'benchtop VIS / UV-VIS spectrophotometers for water analysis', 'prior', NULL);
INSERT INTO products VALUES (584, 2, 'TNTplus', 'barcoded reagent-vial test chemistries', 'prior', NULL);
INSERT INTO products VALUES (584, 3, 'HQ series (HQ1100/HQ4300) with Intellical probes', 'portable and benchtop pH / DO / conductivity meters', 'prior', NULL);
INSERT INTO israel_entities VALUES (584, 'Modotec Ltd.', 'מודוטק בע"מ', 'distributor', 'Hach water/wastewater analysis range per Modotec''s live site (supplier page describes Hach as the world leader in water and wastewater measurement, online and laboratory): online analyzers (BioTector B7000i TOC, Amtax sc ammonium, phosphorus/COD/silica/hardness), SC200/SC1000/SC1500 controllers (Claros), online/lab/portable turbidity and suspended-solids meters, UV and dissolved-oxygen meters, lab spectrophotometers/colorimeters, thermal reactors, incubators, titrators and test kits, portable/fixed samplers; scope therefore wider than the Hach Flow line recorded earlier. Caveat: Modotec''s product pages are roughly 4-7 years old and Hach''s own global-distributor locator did not show Israel in search snippets', 'https://www.modotec.co.il', '+972-4-991-9988', NULL, '16 Moshe Bernstein St., South Industrial Park, Acre (Akko) 2422238', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.modotec.co.il/%D7%A1%D7%A4%D7%A7%D7%99%D7%9D/');
