INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (585, 'haier', 'Haier', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/haier', NULL, NULL, NULL, 'https://www.haiermedical.com', 'prior', 'China', 'סין', 'Qingdao, Shandong', 'Haier Group (controlling shareholder)', 2005, 'Lab refrigeration & cold storage', NULL, NULL, 'multinational consumer electronics and home appliances company based in China', 2800, 2024, 'estimate', 'prior', 323.7, 'CNY 2.329 billion', 'FY2025', 'company', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Ex-Lab''s website was located (ex-lab.com): its live homepage names Haier Biomedical among the brands it supplies and it has live product pages for Haier Biomedical -80C ULT freezers (UltraEco, portable DW-80WZ15), -20C freezers and a Haier vertical autoclave, with installations shown at the Weizmann Institute and Ben-Gurion University; this matches Haier Biomedical''s own live news item naming Ex-Lab as its partner at the Weizmann/Technion expo. Ex-Lab also trades used equipment. Yesh-Lab2 lists a used Haier ULT freezer but is a second-hand dealer, not a channel. A search restricted to haiermedical.com surfaced the news item ''HB Showcases Cutting-Edge Innovations at Israel Expo'', whose snippet says Haier Biomedical''s partner Ex-Lab presented its lineup of laboratory equipment at a university expo hosted by the Weizmann Institute and the Technion, so Ex-Lab is recorded as the Israeli partner on the manufacturer''s own word. Two follow-up searches (unrestricted and .co.il-wide) could not locate Ex-Lab''s website or any Israeli page selling Haier Biomedical ULT freezers (results were Eppendorf, Nordiclab/BDL, Kalstein and household Haier retail), and the distributor-domain search returned nothing. The date of the expo is not visible in the snippet, so the partnership''s current status is unconfirmed. Haier Biomedical''s own news page names Ex-Lab (Petah Tikva) as its Israeli partner; a directory profile says EX-LAB also carries Daihan, DLab, Heal Force, Frimed and Marathon.', '+86 532 8893 7380', 'inquiry@haierbiomedical.com', 'Branding Building, No. 1 Haier Road, Qingdao 266101, Shandong, China (CB Insights lists No. 280 Feng Yuan Road, Qingdao)', 'https://www.haiermedical.com/contact', 'https://disfold.com/company/qingdao-haier-biomedical-co-ltd/', 'Q1143211');
INSERT INTO products VALUES (585, 1, 'DW-86L series', '-86C ultra-low temperature freezers', 'prior', NULL);
INSERT INTO products VALUES (585, 2, 'Automated Biobank', 'automated -80C / LN2 sample storage systems', 'prior', NULL);
INSERT INTO products VALUES (585, 3, 'HXC / HYC series', 'blood bank and pharmacy/vaccine refrigerators', 'prior', NULL);
INSERT INTO israel_entities VALUES (585, 'Ex-Lab', 'אקס-לאב', 'distributor', 'Haier Biomedical laboratory cold-chain and lab equipment: Ex-Lab''s live site (ex-lab.com) names Haier Biomedical among the international brands it supplies (with Daihan Scientific, Frimed, DLab, Marathon) and lists Haier Biomedical -80C ULT freezers (UltraEco; portable DW-80WZ15), -20C lab freezers and a Haier vertical autoclave, with gallery installs at the Weizmann Institute and Ben-Gurion University; Haier Biomedical''s own news page names Ex-Lab as its partner at the Weizmann/Technion expo. Website now identified', 'https://ex-lab.com', NULL, NULL, '4 Nevatim St., Petah Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://ex-lab.com/products/%D7%9E%D7%A7%D7%A4%D7%99%D7%90-%D7%9E%D7%A2%D7%91%D7%93%D7%AA%D7%99-haier-80c/');
