INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (590, 'hanna instruments', 'Hanna Instruments', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/hanna-instruments', NULL, NULL, NULL, 'https://www.hannainst.com', 'prior', 'USA', 'ארה"ב', 'Woonsocket, Rhode Island', NULL, 1978, 'Water & electrochemical analysis', 'כימיקלים ותקנים', 'keyword_guess', NULL, 1500, 2024, 'estimate', 'prior', 150, 'USD ~150 million (trade estimate; private)', '2024 (estimate)', 'estimate', 'prior', 'estimate', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Changed: Hanna''s own live Israel page names Mercury (mercury-ltd.co.il, Gadot Chemicals Group since 2022) as its distributor, with the partnership active since 2023, which settles the official importer question the earlier record left open; Mercury is added as a new entity. Medent remains a current reseller on the strength of its live Hanna product pages and partners page. BioAnalytics and Cannadepot were not re-checked within the search budget and are kept as older evidence. Hanna products are sold in Israel by Medent Scientific Instruments (מדנט מכשור מדעי; an extensive Hanna catalogue of pH/EC/TDS meters, electrodes and photometers on its own site), BioAnalytics (bioanalytics.co.il; Hanna pool/spa and food pH testers) and the online retailer Cannadepot (Hanna portable testers). Hanna''s own ''Find My Hanna'' page lists Israel, but the local contact was not visible in search snippets, so the official importer or exclusive distributor is not established; the companies above may be resellers of that importer.', '+1 401-765-0048', 'intsales@hannainst.com; sales@hannainst.com (US sales/technical service office, Smithfield RI)', '584 Park East Drive, Highland Industrial Park, Woonsocket, RI 02895, USA', 'https://hannainst.com/contact-us/', 'https://hannainst.ec/catalogo/14', 'Q5648691');
