INSERT INTO israel_entities VALUES (590, 'Cannadepot', NULL, 'distributor', 'online retailer; Hanna portable pH/EC/TDS testers', 'https://cannadepot.co.il', NULL, NULL, NULL, NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://cannadepot.co.il/product-category/%D7%9E%D7%93%D7%99%D7%93%D7%94-%D7%95%D7%91%D7%A7%D7%A8%D7%94/hanna-instruments-%D7%9E%D7%9B%D7%A9%D7%99%D7%A8%D7%99%D7%9D-%D7%94%D7%90%D7%A0%D7%94/');
INSERT INTO israel_entities VALUES (590, 'Mercury (mercury-ltd.co.il; part of Gadot Chemicals Group)', 'מרקורי', 'distributor', 'Hanna Instruments'' official distributor for Israel per Hanna''s own live Israel page (pages.hannainst.com/israel): partnership listed as active since 2023; Mercury joined Gadot Chemicals Group in 2022 and offers Israeli research and industry a broad basket of products meeting regulatory requirements; sales and product contacts are on the mercury-ltd.co.il domain', 'https://www.mercury-ltd.co.il', '+972 3-938-7164', NULL, '12 Ha''avoda St., P.O. Box 159, Rosh Ha''ayin', 'https://eng.mercury-ltd.co.il/about_us', 2026, 'new', 'prior_research', NULL, 'https://pages.hannainst.com/israel');
