INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (647, 'ika', 'Ika', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Ika', NULL, NULL, NULL, NULL, 'https://www.ika.com', 'prior', 'Germany', 'גרמניה', 'Staufen im Breisgau', NULL, 1910, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 'ציוד', 'catalog_facet', NULL, 900, 2024, 'company', 'prior', 260, 'USD ~250-273 million (aggregator estimates: Prospeo 250M, ZoomInfo 272.7M); last company-stated figure >EUR 100 million (2014)', 'undated aggregator estimates (c. 2024)', 'estimate', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Medent''s live ''IKA - Germany'' partner page and its live product categories (RCT stirrers, Vortex mixers, RC 2/RC 5 chillers, Oven 125, viscometers) re-confirm Medent as a current Israeli IKA channel. Labotal''s IKA stirrer listing was not re-checked within the budget and is kept as older evidence. IKA''s own dealer locator (ika.com) returned nothing for Israel in a domain-restricted search, so exclusivity is still unknown. Medent''s own site has a dedicated ''IKA - Germany'' manufacturer page and Hebrew product categories listing IKA RCT hot-plate stirrers, vortex mixers, RC 2/RC 5 chillers and the Oven 125, and it says it imports IKA viscometers; Labotal''s overhead-stirrer page names IKA among the brands it stocks, so both are recorded as Israeli distributors. A .co.il-wide search additionally surfaced a 2012 IKA magnetic-stirrer catalogue hosted on master-cold.co.il, which is too old and indirect to record as an entity. IKA''s own dealer locator (ika.com) was not searched within the budget, so the exclusivity or split between Medent and Labotal is unknown.', '+49 7633 831-0', 'sales@ika.de', 'Janke & Kunkel-Straße 10, 79219 Staufen, Germany', NULL, 'https://www.bionity.com/en/companies/7616/', NULL);
INSERT INTO products VALUES (647, 1, 'RCT basic / C-MAG HS', 'magnetic hotplate stirrers', 'prior', NULL);
INSERT INTO products VALUES (647, 2, 'ULTRA-TURRAX T 25 / T 50', 'high-shear dispersers / homogenisers', 'prior', NULL);
INSERT INTO products VALUES (647, 3, 'EUROSTAR / MICROSTAR', 'overhead laboratory stirrers', 'prior', NULL);
