INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (696, 'jeol', 'JEOL USA', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/jeol-usa', NULL, NULL, NULL, 'https://www.jeol.com', 'prior', 'Japan', 'יפן', 'Akishima, Tokyo', NULL, 1949, 'Electron microscopy & X-ray / materials characterization', NULL, NULL, NULL, 3604, 2025, 'company', 'prior', 1202, 'JPY 179,353 million', 'FY ended Mar-2026', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Bargal Analytical Instruments'' live site carries the current JEOL electron-microscopy catalogue with JEOL named as manufacturer (JSM-IT210, JSM-IT200, JSM-IT510, JSM-IT710HR, JCM-7000 NeoScope, JEM-1400Flash, JEM-F200, CRYO ARM 300 and 300 II), confirming the relationship on the distributor side in 2026. The jeol.com service-and-support listing (Bargal, Shoham) did not resurface in this round''s snippets but was not contradicted; NMR/MS coverage remains unconfirmed. Searched ''JEOL Israel distributor/נציג/יבואן'', the brand across the Israeli distributor domains and jeol.com. JEOL''s Service & Support page names Bargal Analytical Instruments (Shoham) as the Israel sales/service contact, and Bargal''s site carries a full JEOL electron-microscopy catalogue plus a news item saying it became JEOL''s new representative in Israel. The jeol.com page is a few years old but matches Bargal''s current site. Whether Bargal also covers JEOL NMR and mass spectrometry was not seen.', '+81 42 543 1111', NULL, '3-1-2 Musashino, Akishima, Tokyo 196-8558, Japan', 'https://www.jeol.com/contacts/products.php', 'https://www.globaldata.com/company-profile/jeol-ltd/locations/', NULL);
