INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (751, 'lauda', 'Lauda', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Lauda', 'https://www.thomassci.com/browse-by/suppliers/lauda', NULL, NULL, NULL, 'https://www.lauda.de', 'prior', 'Germany', 'גרמניה', 'Lauda-Königshofen', NULL, 1956, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 'ציוד', 'catalog_facet', NULL, 600, 2025, 'company', 'prior', 110, 'EUR ~100 million (group)', 'FY2024', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] LAUDA''s own live warranty-participants page names Avni Meshulam & Son Ltd., Haifa, as its authorized sales & service partner for Israel (the same page also shows a LAUDA Ultracool/LAUDA Iberica line against Haifa, apparently a layout artefact), and LAUDA''s locations page lists Israel among countries with representatives, so Avni & Son is upgraded to a confirmed authorised partner. Medent''s live LAUDA category pages re-confirm it as a current laboratory-range channel. Citrine Solutions was not re-checked and is kept as older evidence. Medent''s own site has a ''Lauda - Germany'' manufacturer page describing LAUDA as the global leader in constant-temperature equipment plus a Hebrew product category for LAUDA baths, circulators and chillers, so Medent is the clearest Israeli distributor for the laboratory range. A .co.il-wide search also found Citrine Solutions selling LAUDA Variocool VC 1200, Ultracool UC2 and MGW MS units, and Avni & Son hosting the 2026 LAUDA Ultracool (process chiller) brochure, which suggests an industrial-side partner; both are recorded with caveats because neither page states an authorised-distributor relationship. LAUDA''s own locator (lauda.de) was not searched within the budget.', '+49 9343 503-0', 'info@lauda.de', 'Laudaplatz 1, 97922 Lauda-Königshofen, Germany', 'https://www.lauda.de/de/kontakt', 'https://lauda.de/en/imprint', NULL);
