INSERT INTO israel_entities VALUES (900, 'Gamidor Diagnostics (1984) Ltd.', 'גמידור דיאגנוסטיקה', 'distributor', 'Thermo Scientific / Phadia diagnostics: ImmunoCAP allergy and EliA autoimmune tests (Gamidor states EliA was consolidated under its distribution in Jan 2021 after earlier ImmunoCAP representation); the Mar 2025-Mar 2026 non-exclusive distributor letter for microbiology/diagnostics remains the prior evidence', 'https://www.gamidor.co.il', '+972-3-927-7277', 'info@gamidor.co.il', 'Shaham 32, Petach Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://gamidor.co.il/en/allergy/');
