INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1081, 'revvity', 'Revvity', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Revvity', NULL, NULL, NULL, NULL, 'https://www.revvity.com', 'manual', 'USA', 'ארה"ב', 'Shelton, Connecticut', 'New Mountain Capital', 1937, 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 'ציוד', 'catalog_facet', 'global life sciences and diagnostics company', 6000, 2022, 'company', 'prior', 1300, 'USD 1.3 billion (estimate)', 'FY2022 (at carve-out)', 'estimate', 'prior', 'mixed', 'subsidiary', 'חברה-בת בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] perkinelmer.com''s live office-locations page (location=IL) and its ''PerkinElmer Israel Ltd'' node still list the Ra''anana office with address and phone, confirming the direct subsidiary. ISI Israel Scientific Instruments could not be re-confirmed from its own domain (search returned only SEC filings), so it is kept on the prior perkinelmer.com evidence. Searched PerkinElmer Israel distributor/נציג/יבואן (ICP/GC/FTIR), perkinelmer.com office/distributor pages and a 2024-2026 ''PerkinElmer Israel Ltd'' news search. PerkinElmer set up direct sales/service operations in Israel in August 2013 (press release; GM Aaron Geist named in 2015) and perkinelmer.com currently lists a PerkinElmer Israel office/PerkinElmer Israel Ltd. in Ra''anana plus ISI Israel Scientific Instruments Ltd. (Petach Tikva) as an Israeli partner for food testing. After the 2023 split the Israel entity stayed with the analytical company (now New Mountain Capital-owned PerkinElmer) rather than Revvity; no 2024-2026 Israel-specific news was found, so current staffing/scope of the Ra''anana office rests on the manufacturer''s current listing only.', '1700-500-512 (Israel domestic number)', 'cc.israel@perkinelmer.com', 'Shelton, Connecticut', NULL, 'https://ir.revvity.com/news/investor-news/news-details/2013/PerkinElmer-Establishes-Direct-Operations-in-Israel-08-01-2013/default.aspx', 'Q120467527');
