INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1089, 'roche diagnostics', 'Roche Diagnostics Corp.', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/roche-diagnostics-corp-', NULL, NULL, NULL, 'https://diagnostics.roche.com', 'prior', 'Switzerland', 'שווייץ', 'Rotkreuz (division HQ) / Basel (group HQ)', 'Roche Holding AG', 1968, 'Clinical / IVD laboratory analyzers', 'מכשור אנליטי ומדידה', 'keyword_guess', NULL, 103249, 2024, 'parent', 'prior', 16205, 'CHF 13.85 billion', 'FY2025', 'segment', 'prior', 'reported', 'parent_subsidiary', 'דרך חברת-האם בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Roche''s own live pages confirm a direct diagnostics presence in Israel: the diagnostics safety-officers page lists Roche Diagnostics Israel at 6 Hacharash St., Hod Hasharon, the Roche Diagnostics locations page lists Roche Pharmaceuticals (Israel) Ltd. at the same address, and a May-2026 Roche careers posting for an Application Specialist (Molecular Solutions) in Hod Hasharon shows ongoing local activity. Gamidor (VENTANA tissue diagnostics) and Dyn (Accu-Chek) were re-confirmed on their own live pages, though those pages are dated. A 2025-2026 tender search (''Roche cobas Israel מכרז'') returned only global product news, so no new tender naming the cobas supplier was found. Searched ''"Roche Diagnostics" Israel distributor/נציג/יבואן'', Hebrew ''רוש דיאגנוסטיקה'', the 29 Israeli distributor domains, mr.gov.il tenders and roche.com/diagnostics.roche.com. Roche''s own diagnostics safety-officer page lists ''Roche Diagnostics Israel'' at 6 Hacharash St., Hod Hasharon, and Roche Diagnostics'' office-locations page lists Roche Pharmaceuticals (Israel) Ltd. at the same address; a Hod Hasharon job ad for a Point-of-Care Specialist selling IVD instruments and a Sheba Medical Center tender appendix listing a cobas e801 corroborate direct activity. No independent distributor for cobas/LightCycler was found; Gamidor (VENTANA tissue diagnostics) and Dyn (Diabetes Care) handle only narrow Roche Diagnostics sub-lines. Caveat: no tender award document naming the Israeli affiliate as the cobas supplier was seen.', '+972 9 973 7777', NULL, '6 Hacharash Street, Hod Hasharon 4524079, Israel', 'https://diagnostics.roche.com/me/en/contact-forms/contact-us-support.html', 'https://ichgcp.net/pharma-list/office/84-roche', NULL);
