INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1114, 'sartorius', 'Sartorius', 'D+T+Q', 'https://www.dutscher.com/search?initialFilters=brand:Sartorius', 'https://www.thomassci.com/browse-by/suppliers/sartorius', 'yes', NULL, NULL, 'https://www.sartorius.com', 'prior', 'Germany', 'גרמניה', 'Göttingen', NULL, 1870, 'Bioprocess & filtration', 'מתכלים וציוד קטן', 'catalog_facet', NULL, 14042, 2025, 'company', 'prior', 3892, 'EUR 3,538 million', 'FY2025', 'company', 'prior', 'reported', 'subsidiary', 'חברה-בת בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Sartorius'' own live ''Find your local contact'' page lists Sartorius Israel at Kibbutz Beit Haemek with phone and e-mail, the list-of-companies page and Beit Haemek site news/blog pages confirm the subsidiary. Labotal''s live Hebrew balance guides state it exclusively represents Sartorius in Israel (Cubis II balances, pipettes). Both channels re-confirmed on live pages. Searched Sartorius Israel/Beit HaEmek generically, Sartorius on Israeli distributor domains, sartorius.com and labotal.co.il. Sartorius'' ''local contact'' page lists Sartorius Israel at Kibbutz Beit Haemek 2511500, its list of companies includes Sartorius Israel Ltd., press releases confirm the majority acquisition of Biological Industries (2019) and the June 2021 opening of the Beit Haemek cell-culture-media plant, and a Sartorius job ad for a home-office sales representative in Israel shows in-country sales staff. Lab products: Labotal describes itself on its own site as the exclusive Sartorius representative in Israel for weighing (Cubis II balances) and lists Sartorius pipettes; the filtration channel was not seen. Caveat: a Sartorius Stedim Biotech financial-statement note refers to ''Sartorius Israel Ltd. (51%)'' as not consolidated for materiality, so the legal entity may be a small, partly-owned company distinct from the Beit Haemek production business.', '+972 4 996 0595', 'info@sartorius.com', 'Kibbutz Beit Haemek 2511500, Israel', 'https://www.sartorius.com/en/contact-us/local-contact', 'https://pharmchoices.com/list-of-biotech-companies-in-israel-2/5/', NULL);
INSERT INTO products VALUES (1114, 1, 'Octet BLI systems', 'label-free bio-layer interferometry analyzers', 'prior', NULL);
INSERT INTO products VALUES (1114, 2, 'Biostat STR', 'single-use stirred-tank bioreactors', 'prior', NULL);
INSERT INTO products VALUES (1114, 3, 'Cubis II balances', 'modular premium laboratory balances', 'prior', NULL);
INSERT INTO israel_entities VALUES (1114, 'Sartorius Israel Ltd.', NULL, 'subsidiary', 'Sartorius'' Israeli company at Kibbutz Beit Haemek 2511500 (ex-Biological Industries; cell-culture media production site opened 2021); local contact tel. +972-4-9960595, info.israel@sartorius.com per Sartorius'' live local-contact page', 'https://www.sartorius.com/en/contact-us/local-contact', '+972 4-996-0595', NULL, 'Kibbutz Beit Haemek 2511500', 'https://www.sartorius.com/en/contact-us/local-contact', 2026, 'current', 'prior_research', NULL, 'https://www.sartorius.com/en/contact-us/local-contact');
INSERT INTO israel_entities VALUES (1114, 'Labotal Scientific Equipment', 'לבוטל', 'distributor', 'self-described exclusive Sartorius representative in Israel for weighing (Cubis II balances, isoCAL) and lab products incl. pipettes - live Labotal guide and product pages', 'https://labotal.co.il', '+972 2-579-9222', 'Sales@labotal.co.il', 'Hashalom Rd., Abu Ghosh 9084500 (mail: Mevaseret Zion)', 'https://labotal.co.il/contact/', 2026, 'current', 'prior_research', NULL, 'https://labotal.co.il/המדריך-המקיף-לבחירת-מאזניים-אנליטיים/');
