INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, category, category_source, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1345, 'waters', 'Waters', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/waters', NULL, NULL, NULL, 'https://www.waters.com', 'prior', 'USA', 'ארה"ב', 'Milford, Massachusetts', NULL, 1958, 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 'מכשור אנליטי ומדידה', 'keyword_guess', NULL, 7900, 2025, 'company', 'prior', 3165, 'USD 3,165 million', 'FY2025', 'company', 'prior', 'reported', 'subsidiary', 'חברה-בת בישראל', 'partial', 'חיפוש חלקי', 2024, 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Three searches found no third-party Waters LC/MS distributor in Israel; instead, Israeli government sole-supplier (ספק יחיד) notices on mr.gov.il show Waters (TC) Israel Ltd. supplying Waters HPLC instruments directly to Ministry of Health laboratories (2018-2019) and ''Waters Israel'' holding an LC-MS/MS maintenance contract (2017-2018), i.e. Waters sells and services direct through its own subsidiary, which the Feb-2024 10-K exhibit still lists. waters.com keeps an en_IL locale (Israel training-course list) but its local-office entry was not visible in snippets. Presence therefore reclassified from distributor to subsidiary; the role evidence is 2017-2019 and the entity evidence 2024, so a 2025-26 confirmation is still missing. Bargal (TA Instruments) was not re-searched. Waters'' 10-K Exhibit 21.1 lists an Israeli subsidiary, Waters (TC) Israel Ltd. (seen in a search excerpt; the page itself could not be opened). Whether LC/MS instruments are sold direct or through an Israeli distributor was not established – to verify in the next round. TA Instruments'' Middle East directory lists Bargal (Shoham / Airport City) for thermal analysis, rheology, microcalorimetry, dilatometry and thermal conductivity.', '+1 508 478 2000', NULL, '34 Maple Street, Milford, MA 01757, USA', NULL, 'https://www.globaldata.com/company-profile/waters-corp/locations/', NULL);
INSERT INTO products VALUES (1345, 1, 'ACQUITY Premier UPLC', 'ultra-performance liquid chromatography systems', 'prior', NULL);
